6	\begin{knowledgebox}{最小可复现实验单元}
7	\begin{itemize}
8	    \item 固定任务集合与数据版本；
9	    \item 固定工具接口与权限边界；
10	    \item 固定模型版本与温度参数；
11	    \item 记录完整轨迹与中间状态。
12	\end{itemize}
13	\end{knowledgebox}
