16	\centering
17	\begin{tabular}{p{3.1cm}p{3.3cm}p{2.7cm}p{2.2cm}}
18	\toprule
19	\textbf{实验项} & \textbf{对照设置} & \textbf{主指标} & \textbf{副指标} \\
20	\midrule
21	Reasoning budget & 2k / 6k / 12k tokens & 任务成功率 & 单任务成本 \\
22	Memory policy & 无记忆 / 检索记忆 / 分层记忆 & 长任务完成率 & 错误恢复时长 \\
23	Planning policy & 静态计划 / 动态重规划 & 平均步数 & 无效动作率 \\
24	Verification depth & 终局校验 / 步骤校验 / 双层校验 & 正确率 & 延迟 \\
25	\bottomrule
26	\end{tabular}
27	\caption{Agent 消融实验的基础矩阵}
28	\end{table}
